-- ===== identity =====
CREATE TABLE IF NOT EXISTS goose_identity (
  id integer PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY,
  version_id bigint NOT NULL,
  is_applied boolean NOT NULL,
  tstamp timestamp NOT NULL DEFAULT now()
);
INSERT INTO goose_identity (version_id, is_applied) SELECT 0, true WHERE NOT EXISTS (SELECT 1 FROM goose_identity);

