-- identity/0003_billing_permission.sql
DO $pao_bundle$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM goose_identity WHERE version_id = 3) THEN
    IF EXISTS (SELECT 1 FROM goose_identity WHERE version_id > 3) THEN
      RAISE EXCEPTION 'migrate up: identity/0003_billing_permission.sql is missing (out of order)';
    END IF;
    EXECUTE $pao_stmt$-- Merchant payment review (ADR-0035 §4): super admins and support agents, who already
-- work with providers, confirm or reject payments.
INSERT INTO identity.permissions (name, description) VALUES
    ('billing:manage', 'Review merchant payments and ledgers');$pao_stmt$;
    EXECUTE $pao_stmt$INSERT INTO identity.role_permissions (role, permission) VALUES
    ('support_agent', 'billing:manage'),
    ('super_admin', 'billing:manage');$pao_stmt$;
    INSERT INTO goose_identity (version_id, is_applied) VALUES (3, true);
  END IF;
END
