-- identity/0004_admin_email_index.sql
DO $pao_bundle$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM goose_identity WHERE version_id = 4) THEN
    IF EXISTS (SELECT 1 FROM goose_identity WHERE version_id > 4) THEN
      RAISE EXCEPTION 'migrate up: identity/0004_admin_email_index.sql is missing (out of order)';
    END IF;
    EXECUTE $pao_stmt$-- Admin sign-in and `migrate create-admin` look an admin up by lower(email)
-- (IdentityRepository.AdminByEmail). The unique index on email cannot serve that
-- expression, so each sign-in scanned every account, customers and merchants included.
CREATE INDEX accounts_email_lower_idx ON identity.accounts (lower(email)) WHERE email IS NOT NULL;$pao_stmt$;
    INSERT INTO goose_identity (version_id, is_applied) VALUES (4, true);
  END IF;
END
