-- ===== customer =====
CREATE TABLE IF NOT EXISTS goose_customer (
  id integer PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY,
  version_id bigint NOT NULL,
  is_applied boolean NOT NULL,
  tstamp timestamp NOT NULL DEFAULT now()
);
INSERT INTO goose_customer (version_id, is_applied) SELECT 0, true WHERE NOT EXISTS (SELECT 1 FROM goose_customer);

-- customer/0001_init.sql
DO $pao_bundle$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM goose_customer WHERE version_id = 1) THEN
    IF EXISTS (SELECT 1 FROM goose_customer WHERE version_id > 1) THEN
      RAISE EXCEPTION 'migrate up: customer/0001_init.sql is missing (out of order)';
    END IF;
    EXECUTE $pao_stmt$-- Customer: profiles and saved addresses (C-01, C-02).
CREATE EXTENSION IF NOT EXISTS postgis;$pao_stmt$;
    EXECUTE $pao_stmt$CREATE SCHEMA customer;$pao_stmt$;
    EXECUTE $pao_stmt$CREATE TABLE customer.customers (
    id             uuid PRIMARY KEY,
    name           text        NOT NULL,
    photo_media_id uuid,
    language       text        NOT NULL DEFAULT 'bn' CHECK (language IN ('en', 'bn')),
    created_at     timestamptz NOT NULL DEFAULT now(),
    updated_at     timestamptz NOT NULL DEFAULT now()
);$pao_stmt$;
    EXECUTE $pao_stmt$CREATE TABLE customer.addresses (
    id          uuid PRIMARY KEY,
    customer_id uuid                   NOT NULL REFERENCES customer.customers (id) ON DELETE CASCADE,
    label       text                   NOT NULL CHECK (label IN ('home', 'office', 'other')),
    line1       text                   NOT NULL,
    line2       text                   NOT NULL DEFAULT '',
    area        text                   NOT NULL DEFAULT '',
    location    geography(Point, 4326) NOT NULL,
    is_default  boolean                NOT NULL DEFAULT false,
    created_at  timestamptz            NOT NULL DEFAULT now(),
    updated_at  timestamptz            NOT NULL DEFAULT now()
);$pao_stmt$;
    EXECUTE $pao_stmt$CREATE INDEX addresses_customer_idx ON customer.addresses (customer_id);$pao_stmt$;
    EXECUTE $pao_stmt$CREATE INDEX addresses_location_gist ON customer.addresses USING gist (location);$pao_stmt$;
    EXECUTE $pao_stmt$CREATE UNIQUE INDEX addresses_one_default ON customer.addresses (customer_id) WHERE is_default;$pao_stmt$;
    EXECUTE $pao_stmt$-- Events written in the same transaction as the change; the relay delivers them
-- at least once, in order per aggregate (PRD §9.3 rule 5).
CREATE TABLE customer.outbox (
    id           uuid PRIMARY KEY,
    aggregate_id text        NOT NULL,
    event_name   text        NOT NULL,
    payload      jsonb       NOT NULL,
    created_at   timestamptz NOT NULL DEFAULT now(),
    published_at timestamptz,
